namespace Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\Theme\Domain\ValueObject\ThemeVersionVO;

trait ThemeVersionAccessor {
  private ?ThemeVersionVO $_version = null;
  public function getVersion(): ?int
  {
    return $this->_version?->value();
  }
  public function version(): ?ThemeVersionVO
  {
    return $this->_version;
  }
  public function isVersionChanged(?self $original = null): bool
  {
  return null !== $this->_version && !$this->_version->equals( $original?->_version );  }
  public function withVersion(ThemeVersionVO|int|null $version): self
  {
    $copy = clone $this;
    $copy->_version = ThemeVersionVO::from( $version );
    return $copy;
  }
}